entries[102245] = { ["name"] = "Qian-Le, Courage of Niuzao", ["text"] = "Binds when picked up\nBack\n1525 Armor\n+1,716 Agility\n+2,694 Stamina\n+ 918 Critical Strike\n+ 918 Expertise\n+ 918 Mastery\n\nRed Socket\nSocket Bonus: + 90 Stamina\nRequires Level 90\nEquip: The Endurance of Niuzao fully absorbs the damage of one attack that would normally kill you. This effect has a 2 min cooldown. Does not function for non-Tank-specialized characters." }
entries[102246] = { ["name"] = "Xing-Ho, Breath of Yu'lon", ["text"] = "Binds when picked up\nBack\n1525 Armor\n+2,694 Stamina\n+1,716 Intellect\n+ 918 Critical Strike\n+ 918 Haste\n+ 918 Mastery\n\nRed Socket\nSocket Bonus: + 60 Intellect\nRequires Level 90\nEquip: Your damaging spell casts have a chance to empower you with the Essence of Yu'lon, causing you to hurl jade dragonflame at the target, dealing 1 damage over 4 sec. This damage also affects up to 4 other enemies near the burning target. (Approximately 2.61 procs per minute)" }
entries[102247] = { ["name"] = "Jina-Kang, Kindness of Chi-Ji", ["text"] = "Binds when picked up\nBack\n1525 Armor\n+2,694 Stamina\n+1,716 Intellect\n+918 Spirit\n+ 918 Haste\n+ 918 Mastery\n\nRed Socket\nSocket Bonus: + 60 Intellect\nRequires Level 90\nEquip: Your helpful spells have a chance to grant you Spirit of Chi-Ji, increasing all healing done by 5% and causing all overhealing on players to be redistributed to up to 5 nearby injured friends, for 10 sec. (Approximately 0.58 procs per minute)" }
