entries[102614] = { ["name"] = "Prideful Gladiator's Wyrmhide Robes", ["text"] = "Season 15\nBinds when picked up\nChest Leather\n3412 Armor\n+3,035 Stamina\n+1,863 Intellect\n+ 1,189 Critical Strike\n+ 1,349 Haste\n+ 808 PvP Power\n\nRed Socket\nYellow Socket\nSocket Bonus: + 120 PvP Power\n\nDurability 165 / 165\nClasses: Druid\nRequires any Alliance race\nRequires Level 90\n\nGladiator's Wildhide (0/5)\nGladiator's Wyrmhide Gloves\nGladiator's Wyrmhide Helm\nGladiator's Wyrmhide Legguards\nGladiator's Wyrmhide Robes\nGladiator's Wyrmhide Spaulders\n(2) Set : Increases PvP power by 500.\n(2) Set : While not in an Eclipse state critical attacks done to you restore 20 Solar or 20 Lunar energy whichever is more beneficial to you. This effect can only occur once every 6 sec.\n(4) Set : Increases PvP Power by 1000.\n(4) Set : Your Astral Communion ability can be used while moving.\nSell Price:" }
entries[102615] = { ["name"] = "Prideful Gladiator's Mooncloth Gloves", ["text"] = "Season 15\nBinds when picked up\nHands Cloth\n1675 Armor\n+2,254 Stamina\n+1,423 Intellect\n+922 Spirit\n+ 1,002 Haste\n+ 600 PvP Power\n\nBlue Socket\nSocket Bonus: + 60 Intellect\n\nDurability 60 / 60\nClasses: Priest\nRequires any Alliance race\nRequires Level 90\nEquip: Reduces the cooldown of your Psychic Scream ability by 3 sec.\n\nGladiator's Investiture (0/5)\nGladiator's Mooncloth Gloves\nGladiator's Mooncloth Helm\nGladiator's Mooncloth Leggings\nGladiator's Mooncloth Robe\nGladiator's Mooncloth Mantle\n(2) Set : Increases PvP power by 500.\n(2) Set : When you cast Prayer of Mending, the initial target is blessed with a Holy Spark increasing the healing done by your next Flash Heal, Greater Heal or Holy Word: Serenity by 50% for 10 sec.\n(4) Set : Increases PvP Power by 1000.\n(4) Set : Reduces the cooldown of your Chakra to 5 sec. During Spirit Shell, the mana cost of your Flash Heal is reduced by 50%.\nSell Price:" }
